// Контракт хранилища: один интерфейс на любое место — кэш внешнего API,
// бронь отправки, счётчик. Чем хранилище отличается (память процесса, Postgres,
// Redis), видно по тому, какие методы у него есть, а не по имени.

/** Значение или обещание: память отвечает сразу, сетевые хранилища — позже. */
export type MaybePromise<T> = T | Promise<T>

/** Параметры области ключей. */
export interface ScopeOptions {
  /**
   * Потолок записей в области. Учитывается хранилищами, которые вытесняют сами
   * (память процесса). Сетевые хранилища живут по своим правилам вытеснения и
   * этот параметр игнорируют.
   */
  max?: number
}

/**
 * Хранилище «ключ → значение со сроком». Срок обязателен: в кэше нет вечных
 * записей. «Без срока» пишется явно — `Infinity`.
 *
 * Значения должны быть JSON-совместимыми. Память держит их по ссылке и не
 * копирует, сетевые хранилища сериализуют. Код, который работает с одним,
 * должен работать и с другим, поэтому записанное значение не меняют.
 */
export interface Store {
  /** Значение или `undefined`, если ключа нет или срок истёк. */
  get<T>(key: string): MaybePromise<T | undefined>
  /** Записать или заменить. Срок — в миллисекундах от текущего момента. */
  set<T>(key: string, value: T, ttlMs: number): MaybePromise<void>
  delete(key: string): MaybePromise<void>
  /** Удалить всё в ЭТОЙ области (и в её вложенных областях). */
  clear(): MaybePromise<void>
  /**
   * Вложенная область: ключи получают префикс `name:`, у памяти — свой потолок.
   * Два места с разными именами не перетирают ключи друг друга и не вытесняют
   * чужие записи. Повторный вызов с тем же именем отдаёт ту же область.
   */
  scope(name: string, options?: ScopeOptions): Store
}

/**
 * Хранилище с атомарными операциями. Нужно там, где ошибка = двойное
 * выполнение или превышение предела: бронь отправки, счётчики.
 */
export interface AtomicStore extends Store {
  /** Записать, только если ключа нет. `true` — записали, `false` — ключ занят. */
  add<T>(key: string, value: T, ttlMs: number): MaybePromise<boolean>
  /**
   * Прибавить 1 и вернуть новое значение. Срок ставится, когда ключ создаётся,
   * и не продлевается последующими вызовами (фиксированное окно).
   */
  incr(key: string, ttlMs: number): MaybePromise<number>
  scope(name: string, options?: ScopeOptions): AtomicStore
}

/** Есть ли у хранилища атомарные операции. */
export function isAtomic(store: Store): store is AtomicStore {
  const s = store as Partial<AtomicStore>
  return typeof s.add === 'function' && typeof s.incr === 'function'
}

/**
 * Проверка при ПОДКЛЮЧЕНИИ, а не на первом запросе: место, которому нужна
 * атомарность, падает сразу и объясняет почему. Тихая эмуляция `add` через
 * `get` + `set` дала бы гонку, то есть ровно ту ошибку, от которой защищаемся.
 * @param store Хранилище, которое передали месту.
 * @param who Кто требует: попадает в текст ошибки.
 * @returns То же хранилище, суженное до `AtomicStore`.
 */
export function requireAtomic(store: Store, who: string): AtomicStore {
  if (!isAtomic(store))
    throw new TypeError(`[cache] ${who}: нужно хранилище с атомарными add/incr`)
  return store
}
